const update=$input.first().json;
const cb=update.callback_query;
const m=cb?.message||update.message||{};
const cfg=$('Настройки доступа').first().json;
const allowed=String(cfg.allowedChatIds||'').split(',').map(s=>s.trim()).filter(Boolean);
const chatId=String(m.chat?.id||'');
if(!chatId) return [];
if(cb){
 const match=/^ra:([ax]):([A-Za-z0-9_-]{1,48})$/.exec(String(cb.data||''));
 const permitted=m.chat?.type==='private'&&allowed.includes(chatId)&&String(cb.from?.id||'')===chatId&&Number.isSafeInteger(m.message_id)&&!!cb.id&&!!match;
 return [{json:{chatId,route:permitted?3:4,reason:permitted?'':'Эта кнопка недоступна. Отправьте новый отчёт.',callbackId:String(cb.id||''),callbackAction:match?.[1]==='a'?'approve':'cancel',draftToken:match?.[2]||'',previewMessageId:String(m.message_id||'')}}];
}
const supported=/\.(mp3|wav|m4a|ogg|oga|flac|mp4|mpeg|mpga|webm)$/i;
const a=m.voice||m.audio||(supported.test(m.document?.file_name||'')?m.document:null);
let route=2, reason='Отправьте один полный отчёт о ремонте текстом, голосовым или аудиофайлом. Укажите технику, неисправность, работы, результат проверки и мастера. Цены и запчасти - только если они известны. Пример: /help.';
if(m.chat?.type!=='private') {reason='Для отчётов используйте личный чат с ботом.';}
else if(!allowed.includes(chatId)){reason='Доступ ещё не настроен. Передайте администратору ваш chat ID: '+chatId+'. Аудио не загружалось и не отправлялось на распознавание.';}
else if(/^\/(start|help|example|пример)(@\w+)?(?:\s|$)/i.test(m.text||'')) {reason="Как подготовить акт ремонта\n\nОтправьте один полный отчёт голосом, аудиофайлом или текстом. Говорите обычными словами — по строгому шаблону диктовать не нужно.\n\nПример, что сказать голосом:\n«Меня зовут Алексей, я мастер. Ремонтировал стиральную машину Samsung. Неисправен был барабан. Заменил барабан. Один барабан стоил 2300 тенге, работа — 5000 тенге. После ремонта проверил: машина стирает, барабан работает.»\n\nТекстом можно отправить тот же рассказ.\nЭто вымышленный пример — замените технику, имя и суммы своими.\n\nОбязательно: кто мастер, какая техника, что сломалось, что сделали и как проверили после ремонта.\nЕсли есть цены — назовите валюту (например, тенге) и отдельно стоимость запчастей и работы. Неизвестные данные не придумывайте.\nПо возможности добавьте модель, серийный номер, заказчика и дату. Если запчастей не было, так и скажите.\n\nЗатем проверьте черновик и нажмите «Создать PDF». Кнопка «Исправить» отменяет черновик — после неё отправьте полный исправленный отчёт.\n\nПоказать этот пример снова: /help или /example.";}
else if(a){
 if((a.file_size||0)>19*1024*1024) reason='Файл слишком большой. Для этой версии отправьте аудио до 19 МБ или текст.';
 else {route=1;reason='';}
}else if(m.text?.trim()){
 if(m.text.trim().length>12000) reason='Отчёт слишком длинный. Отправьте до 12 000 символов.';
 else {route=0;reason='';}
}
return [{json:{chatId,route,reason,report:m.text?.trim()||'',caption:m.caption||'',fileId:a?.file_id||'',mimeType:a?.mime_type||'audio/ogg',sourceMessageId:m.message_id,sourceUpdateId:$input.first().json.update_id}}];

const origin=$('Вход и ограничения').first().json;
const transcription=$input.first().json.text;
const report=origin.route===1 ? [String(transcription||'').trim(),origin.caption].filter(Boolean).join('\nДополнение: ') : origin.report;
if(!report||report.length>16000) throw new Error('Пустой или слишком длинный отчёт');
return [{json:{...origin,report}}];

const origin=$('Текст отчёта').first().json;
let a=$input.first().json.output;
if(typeof a==='string') a=JSON.parse(a);
if(!a||typeof a!=='object') throw new Error('Нет структурированного отчёта');
const clean=(v,max=1200)=>typeof v==='string'?v.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,'').trim().slice(0,max):'';
const fields=['device','model','serial','client','technician','repairDate','fault','currency','testResult','recommendations'];
for(const f of fields)a[f]=clean(a[f]);
a.work=Array.isArray(a.work)?a.work.map(x=>clean(x,500)).filter(Boolean).slice(0,30):[];
a.parts=Array.isArray(a.parts)?a.parts.slice(0,30).map(p=>({name:clean(p.name,200),quantity:p.quantity,unitPrice:p.unitPrice})):[];
const problems=[];
for(const [f,label] of [['device','тип техники'],['technician','имя мастера'],['fault','неисправность'],['testResult','результат проверки']])if(!a[f])problems.push(label);
if(!a.work.length)problems.push('выполненные работы');
if(a.repairDate&&!/^\d{4}-\d{2}-\d{2}$/.test(a.repairDate))problems.push('дата в формате ГГГГ-ММ-ДД');
if(a.repairDate&&/^\d{4}-\d{2}-\d{2}$/.test(a.repairDate)){
 const d=new Date(a.repairDate+'T00:00:00Z');if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==a.repairDate)problems.push('корректная дата ремонта');
}
const numeric=v=>v===null||(typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<=1e9);
if(!numeric(a.laborCost))problems.push('корректная стоимость работ');
for(const p of a.parts)if(!p.name||!numeric(p.quantity)||p.quantity===0||!numeric(p.unitPrice))problems.push('корректные данные запчастей');
a.uncertainties=Array.isArray(a.uncertainties)?a.uncertainties.map(x=>clean(x,250)).filter(Boolean).slice(0,10):[];

if(!['not_stated','none','listed'].includes(a.partsStatus)||(a.partsStatus==='listed'&&!a.parts.length)||(a.partsStatus!=='listed'&&a.parts.length))problems.push('статус использования запчастей');
const hasPrices=a.laborCost!==null||a.parts.some(p=>p.unitPrice!==null);
if(!hasPrices)a.uncertainties=a.uncertainties.filter(x=>!/^уточните валюту цен$/i.test(x));
if(a.uncertainties.length)problems.push('неоднозначности: '+a.uncertainties.join('; '));
if(hasPrices&&!a.currency&&!a.uncertainties.some(x=>/^уточните валюту цен$/i.test(x)))problems.push('валюта для указанных цен');
const round=n=>Math.round((n+Number.EPSILON)*100)/100;
const knownParts=a.partsStatus==='none'||(a.partsStatus==='listed'&&a.parts.length>0&&a.parts.every(p=>p.quantity!==null&&p.unitPrice!==null));
const partsTotal=knownParts?round(a.parts.reduce((s,p)=>s+round(p.quantity*p.unitPrice),0)):null;
const total=partsTotal!==null&&a.laborCost!==null?round(partsTotal+a.laborCost):null;
const val=v=>v||'не указано';
const money=n=>n===null?'не указана':n.toLocaleString('ru-RU',{maximumFractionDigits:2})+(a.currency?' '+a.currency:'');
const number='R-'+String(origin.sourceUpdateId);
const works=a.work.map((x,i)=>(i+1)+'. '+x).join('\n');
const parts=a.parts.length?a.parts.map((p,i)=>(i+1)+'. '+p.name+'; количество: '+(p.quantity??'не указано')+'; цена за ед.: '+money(p.unitPrice)+'; сумма: '+money(p.quantity!==null&&p.unitPrice!==null?round(p.quantity*p.unitPrice):null)).join('\n'):(a.partsStatus==='none'?'По отчёту мастера запчасти не использовались.':'В отчёте запчасти не указаны; их стоимость неизвестна.');
const docText=[
'АКТ ВЫПОЛНЕННЫХ РАБОТ ПО РЕМОНТУ ТЕХНИКИ', '№ '+number,
'Статус: подготовлен по отчёту мастера, без подписей сторон.',
'Дата ремонта: '+val(a.repairDate), 'Заказчик: '+val(a.client),'Мастер: '+val(a.technician),
'', '1. ТЕХНИКА','Наименование: '+val(a.device),'Модель: '+val(a.model),'Серийный номер: '+val(a.serial),
'', '2. НЕИСПРАВНОСТЬ',val(a.fault),'','3. ВЫПОЛНЕННЫЕ РАБОТЫ',works,
'','4. ЗАПЧАСТИ И МАТЕРИАЛЫ',parts,'','5. СТОИМОСТЬ',
'Работы: '+money(a.laborCost),'Запчасти: '+money(partsTotal),'Итого: '+money(total),
total===null?'Полная сумма не рассчитана: не все цены/количества указаны.':'Сумма рассчитана из указанных в отчёте значений.',
'', '6. ПРОВЕРКА И РЕКОМЕНДАЦИИ','Результат проверки: '+val(a.testResult),'Рекомендации: '+val(a.recommendations),
'', 'Мастер: __________________ / __________________','Заказчик: _______________ / __________________',
'', 'Дата подписания: __________________','Условия гарантии: заполняются сторонами отдельно.',
'Подтверждение черновика в боте не является подписью заказчика и не подтверждает оплату.'
].join('\n');
const preview=[
'Проверьте черновик '+number, 'Техника: '+val(a.device)+' / '+val(a.model),
'С/н: '+val(a.serial), 'Заказчик: '+val(a.client),'Мастер: '+val(a.technician),
'Дата: '+val(a.repairDate),'Неисправность: '+val(a.fault),'Работы:\n'+works,
'Запчасти:\n'+parts,'Работы: '+money(a.laborCost),'Итого: '+money(total),
'Проверка: '+val(a.testResult),'Рекомендации: '+val(a.recommendations),
'Если всё верно, подтвердите выпуск PDF. Это не подписание акта заказчиком. Для исправлений отклоните и отправьте новый полный отчёт.'
].join('\n');
if(preview.length>3700)problems.push('более короткий отчёт для проверки в Telegram');
return [{json:{...origin,act:a,number,partsTotal,total,valid:problems.length===0,docText,preview:preview.slice(0,3700),request:(origin.route===1?'Голосовое получено и распознано.\nЯ услышал: «'+clean(origin.report,1700)+'»\n\n':'')+'Для черновика нужно уточнить: '+[...new Set(problems)].join('; ')+'.\nОтправьте полный отчёт с уточнениями текстом или голосом. Не нужно произносить названия полей — расскажите обычными словами. Каждый отчёт обрабатывается отдельно.'}}];

const origin=$('Вход и ограничения').first().json;
const row=$input.first().json;
const invalid=()=>[{json:{...origin,valid:false,reason:'Этот черновик уже обработан, устарел или недоступен. Если PDF уже пришёл, повтор не нужен. Для нового ремонта отправьте новый полный отчёт.'}}];
if(!row.id||row.token!==origin.draftToken||String(row.chatId)!==origin.chatId||String(row.telegramMessageId)!==origin.previewMessageId||String(row.claimExecutionId)!==String($execution.id)||!Number.isFinite(Date.parse(row.expiresAt))||Date.parse(row.expiresAt)<=Date.now())return invalid();
let draft;try{draft=JSON.parse(row.payload);}catch{return invalid();}
if(!draft||draft.valid!==true||draft.chatId!==origin.chatId||typeof draft.docText!=='string'||!draft.docText.trim()||draft.docText.length>50000||typeof draft.preview!=='string'||draft.preview.length>3700||!/^R-\d+$/.test(draft.number)||!['approve','cancel'].includes(origin.callbackAction))return invalid();
return [{json:{...draft,valid:true,draftRowId:row.id,draftToken:row.token,callbackAction:origin.callbackAction,previewMessageId:origin.previewMessageId}}];
